+		case EditorExportPreset::EXPORT_CUSTOMIZED: {
+			EditorExportPlatformUtils::export_find_customized_resources(p_preset, EditorFileSystem::get_singleton()->get_filesystem(), p_preset->get_file_export_mode("res://"), p_paths);
