+void EditorExportPlatformUtils::AsyncPckFileDependenciesState::add_to_file_dependencies(const HashSet<String> &p_file_set) {
+	for (const String &file : p_file_set) {
+		if (file.ends_with("/")) {
+			continue;
+		}
+		add_to_file_dependencies(file);
+	}
